from pathlib import Path
import subprocess,json,statistics,sys,shutil
root=Path('/Users/chazu/dev/zig/birnam-oop-id');work=Path('/tmp/oop-simplify-20261023');name=sys.argv[1];previous=sys.argv[2] if len(sys.argv)>2 else 'before'
after=work/name;after.mkdir(exist_ok=True)
for lib in ['id','root_registry','collect']:shutil.copyfile(root/'.cargo-target/oop-slice/release'/f'libbirnam_{lib}.dylib',after/f'libbirnam_{lib}.dylib')
runs=[]
for i,lane in enumerate([previous,name,name,previous,previous,name,name,previous]):
 lib=work/lane;args=[str(root/'.cargo-target/oop-slice/fixtures/bench-v2'),*[str(lib/f'libbirnam_{n}.dylib')for n in ['id','root_registry','collect']]]
 r=subprocess.run(args,check=True,capture_output=True,text=True);runs.append({'order':i,'variant':lane,'rows':[json.loads(l)for l in r.stdout.splitlines()]})
s={}
for case in ['allocate-and-retain-eighth','intern-existing-64','produce-and-intern-new-64','collect-garbage']:
 ns={lane:statistics.median(row['ns_per_op']for run in runs if run['variant']==lane for row in run['rows']if row.get('case')==case)for lane in [previous,name]}
 s[case]={'median_ns':ns,'change_percent':100*(ns[name]/ns[previous]-1)}
output={'runs':runs,'summary':s};(work/f'{name}-timings.json').write_text(json.dumps(output,indent=2)+'\n');print(json.dumps(s,indent=2))
